UPDATE xsy_mall_cart_item
SET quantity = #{quantity}, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE account_id = #{accountId} AND sku_id = #{skuId} AND deleted = FALSE

